import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { children, splitProps } from 'solid-js';
import styles from './Table.module.css';

type TableDataProps = {
  'data-scope'?: string;
  'data-part'?: string;
  'data-slot'?: string;
};

type TableRootProps = HTMLArkProps<'table'> &
  TableDataProps & {
    interactive?: boolean;
    showColumnBorder?: boolean;
    size?: 'sm' | 'md' | 'lg';
    stickyHeader?: boolean;
    striped?: boolean;
    variant?: 'line' | 'outline';
    'data-interactive'?: string | boolean;
    'data-show-column-border'?: string | boolean;
    'data-size'?: string;
    'data-sticky-header'?: string | boolean;
    'data-striped'?: string | boolean;
    'data-variant'?: string;
  };

type TableScrollAreaProps = HTMLArkProps<'div'> & TableDataProps;
type TableCaptionProps = HTMLArkProps<'caption'> &
  TableDataProps & {
    side?: 'top' | 'bottom';
    'data-side'?: string;
  };
type TableColumnGroupProps = HTMLArkProps<'colgroup'> & TableDataProps;
type TableColumnProps = HTMLArkProps<'col'> &
  TableDataProps & {
    htmlWidth?: string | number;
  };
type TableHeaderProps = HTMLArkProps<'thead'> & TableDataProps;
type TableBodyProps = HTMLArkProps<'tbody'> & TableDataProps;
type TableFooterProps = HTMLArkProps<'tfoot'> & TableDataProps;
type TableRowProps = HTMLArkProps<'tr'> & TableDataProps;
type TableColumnHeaderProps = HTMLArkProps<'th'> &
  TableDataProps & {
    numeric?: boolean;
    'data-numeric'?: string | boolean;
  };
type TableCellProps = HTMLArkProps<'td'> &
  TableDataProps & {
    numeric?: boolean;
    'data-numeric'?: string | boolean;
  };
type TableEmptyProps = HTMLArkProps<'td'> &
  TableDataProps & {
    colSpan: number;
  };

function TableRoot(props: TableRootProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-interactive',
    'data-part',
    'data-scope',
    'data-show-column-border',
    'data-size',
    'data-slot',
    'data-sticky-header',
    'data-striped',
    'data-variant',
    'interactive',
    'showColumnBorder',
    'size',
    'stickyHeader',
    'striped',
    'variant',
  ]);

  return (
    <ark.table
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="root"
      data-slot="table-root"
      data-interactive={local.interactive || undefined}
      data-show-column-border={local.showColumnBorder || undefined}
      data-size={local.size ?? 'md'}
      data-sticky-header={local.stickyHeader || undefined}
      data-striped={local.striped || undefined}
      data-variant={local.variant ?? 'line'}
      class={clsx(styles.root, local.class)}
    />
  );
}

function TableScrollArea(props: TableScrollAreaProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
  ]);

  return (
    <ark.div
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="scroll-area"
      data-slot="table-scroll-area"
      class={clsx(styles.scrollArea, local.class)}
    />
  );
}

function TableCaption(props: TableCaptionProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-side',
    'data-slot',
    'side',
  ]);

  return (
    <ark.caption
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="caption"
      data-side={local.side ?? 'bottom'}
      data-slot="table-caption"
      class={clsx(styles.caption, local.class)}
    />
  );
}

function TableColumnGroup(props: TableColumnGroupProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
  ]);

  return (
    <ark.colgroup
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="column-group"
      data-slot="table-column-group"
      class={local.class}
    />
  );
}

function TableColumn(props: TableColumnProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
    'htmlWidth',
    'width',
  ]);

  return (
    <ark.col
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="column"
      data-slot="table-column"
      width={local.htmlWidth ?? local.width}
      class={local.class}
    />
  );
}

function TableHeader(props: TableHeaderProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
  ]);

  return (
    <ark.thead
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="header"
      data-slot="table-header"
      class={clsx(styles.header, local.class)}
    />
  );
}

function TableBody(props: TableBodyProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
  ]);

  return (
    <ark.tbody
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="body"
      data-slot="table-body"
      class={clsx(styles.body, local.class)}
    />
  );
}

function TableFooter(props: TableFooterProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
  ]);

  return (
    <ark.tfoot
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="footer"
      data-slot="table-footer"
      class={clsx(styles.footer, local.class)}
    />
  );
}

function TableRow(props: TableRowProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-part',
    'data-scope',
    'data-slot',
  ]);

  return (
    <ark.tr
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="row"
      data-slot="table-row"
      class={clsx(styles.row, local.class)}
    />
  );
}

function TableColumnHeader(props: TableColumnHeaderProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-numeric',
    'data-part',
    'data-scope',
    'data-slot',
    'numeric',
  ]);

  return (
    <ark.th
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="column-header"
      data-numeric={local.numeric || undefined}
      data-slot="table-column-header"
      class={clsx(styles.columnHeader, local.numeric && styles.numeric, local.class)}
    />
  );
}

function TableCell(props: TableCellProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-numeric',
    'data-part',
    'data-scope',
    'data-slot',
    'numeric',
  ]);

  return (
    <ark.td
      asChild={local.asChild}
      {...others}
      data-scope="table"
      data-part="cell"
      data-numeric={local.numeric || undefined}
      data-slot="table-cell"
      class={clsx(styles.cell, local.numeric && styles.numeric, local.class)}
    />
  );
}

function TableEmpty(props: TableEmptyProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'children',
    'class',
    'colSpan',
    'data-part',
    'data-scope',
    'data-slot',
  ]);
  const resolvedChildren = children(() => local.children);

  return (
    <ark.tr data-scope="table" data-part="row" data-empty data-slot="table-row" class={styles.row}>
      <ark.td
        asChild={local.asChild}
        {...others}
        data-scope="table"
        data-part="empty"
        data-slot="table-empty"
        colSpan={local.colSpan}
        class={clsx(styles.cell, styles.empty, local.class)}
      >
        {resolvedChildren() ?? 'No results.'}
      </ark.td>
    </ark.tr>
  );
}

const Table = Object.assign(TableRoot, {
  Root: TableRoot,
  ScrollArea: TableScrollArea,
  Caption: TableCaption,
  ColumnGroup: TableColumnGroup,
  Column: TableColumn,
  Header: TableHeader,
  Body: TableBody,
  Footer: TableFooter,
  Row: TableRow,
  ColumnHeader: TableColumnHeader,
  Cell: TableCell,
  Empty: TableEmpty,
});

export { Table };

@layer moduix.components {
  .scrollArea {
    box-sizing: border-box;
    position: relative;
    width: 100%;
    min-width: 0;
    overflow-x: auto;
    isolation: isolate;
    border: var(
        --moduix-table-scroll-area-border-width,
        var(--moduix-table-border-width, var(--moduix-border-width-sm))
      )
      solid
      var(
        --moduix-table-scroll-area-border-color,
        var(--moduix-table-border-color, var(--moduix-color-border))
      );
    border-radius: var(--moduix-table-scroll-area-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-table-scroll-area-bg, var(--moduix-color-card));
    box-shadow: var(--moduix-table-scroll-area-shadow, none);
  }

  .root {
    --_table-cell-padding-x-default: var(--moduix-table-cell-padding-x, var(--moduix-spacing-4));
    --_table-cell-padding-y-default: var(--moduix-table-cell-padding-y, var(--moduix-spacing-3));
    --_table-empty-padding-y-default: calc(var(--_table-cell-padding-y-default) * 2);

    box-sizing: border-box;
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    color: var(--moduix-table-color, var(--moduix-color-foreground));
    font-family: var(--moduix-table-font-family, inherit);
    font-size: var(--moduix-table-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-table-line-height, var(--moduix-line-height-text-sm));
    text-align: left;
    isolation: isolate;

    &[data-size='sm'] {
      --_table-cell-padding-x-default: var(--moduix-table-cell-padding-x, var(--moduix-spacing-3));
      --_table-cell-padding-y-default: var(--moduix-table-cell-padding-y, var(--moduix-spacing-2));
      font-size: var(--moduix-table-font-size-sm, var(--moduix-text-xs));
      line-height: var(--moduix-table-line-height-sm, var(--moduix-line-height-text-xs));
    }

    &[data-size='lg'] {
      --_table-cell-padding-x-default: var(--moduix-table-cell-padding-x, var(--moduix-spacing-5));
      --_table-cell-padding-y-default: var(--moduix-table-cell-padding-y, var(--moduix-spacing-4));
      font-size: var(--moduix-table-font-size-lg, var(--moduix-text-md));
      line-height: var(--moduix-table-line-height-lg, var(--moduix-line-height-text-md));
    }

    &[data-variant='outline'] {
      border: var(--moduix-table-border-width, var(--moduix-border-width-sm)) solid
        var(--moduix-table-border-color, var(--moduix-color-border));
    }
  }

  .caption {
    box-sizing: border-box;
    color: var(--moduix-table-caption-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-table-caption-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-table-caption-line-height, var(--moduix-line-height-text-sm));
    padding-inline: var(--moduix-table-caption-padding-x, var(--_table-cell-padding-x-default));
    text-align: left;
    text-wrap: pretty;

    &[data-side='top'] {
      caption-side: top;
      padding-block: var(--moduix-table-caption-padding-edge, var(--moduix-spacing-2))
        var(--moduix-table-caption-padding-y, var(--moduix-spacing-3));
    }

    &[data-side='bottom'] {
      caption-side: bottom;
      padding-block: var(--moduix-table-caption-padding-y, var(--moduix-spacing-3))
        var(--moduix-table-caption-padding-edge, var(--moduix-spacing-2));
    }
  }

  .row {
    transition: var(
      --moduix-table-row-transition,
      background-color var(--moduix-transition-default)
    );
  }

  .header .row,
  .body .row {
    border-bottom: var(--moduix-table-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
  }

  .root[data-striped] .body .row:nth-child(even):not([data-empty]) {
    background-color: var(
      --moduix-table-row-bg-striped,
      color-mix(in oklab, var(--moduix-color-muted) 35%, transparent)
    );
  }

  .root[data-interactive] .body .row:not([data-empty]):hover {
    background-color: var(--moduix-table-row-bg-hover, var(--moduix-color-muted));
  }

  .root[data-interactive] .body .row:not([data-empty]):focus-within {
    background-color: var(
      --moduix-table-row-bg-focus,
      var(--moduix-table-row-bg-hover, var(--moduix-color-muted))
    );
  }

  .root[data-show-column-border] :is(.columnHeader, .cell):not(:last-child) {
    border-inline-end: var(
        --moduix-table-column-border-width,
        var(--moduix-table-border-width, var(--moduix-border-width-sm))
      )
      solid
      var(
        --moduix-table-column-border-color,
        var(--moduix-table-border-color, var(--moduix-color-border))
      );
  }

  .root[data-sticky-header] .header {
    position: sticky;
    inset-block-start: 0;
    z-index: var(--moduix-table-sticky-header-z-index, 3);
    background-color: var(
      --moduix-table-sticky-header-bg,
      var(--moduix-table-scroll-area-bg, var(--moduix-color-card))
    );
  }

  .body .row:last-child {
    border-bottom: 0;
  }

  .footer {
    border-top: var(--moduix-table-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-table-border-color, var(--moduix-color-border));
    background-color: var(--moduix-table-footer-bg, var(--moduix-color-muted));
    color: var(
      --moduix-table-footer-color,
      var(--moduix-table-color, var(--moduix-color-foreground))
    );
    font-weight: var(--moduix-table-footer-font-weight, var(--moduix-weight-medium));
  }

  .columnHeader,
  .cell {
    position: relative;
    z-index: 0;
    padding-block: var(--_table-cell-padding-y-default);
    padding-inline: var(--_table-cell-padding-x-default);
    vertical-align: middle;

    &[data-sticky='start'] {
      position: sticky;
      inset-inline-start: 0;
      z-index: var(--moduix-table-sticky-column-z-index, 2);
      background-color: var(
        --moduix-table-sticky-column-bg,
        var(--moduix-table-scroll-area-bg, var(--moduix-color-card))
      );
    }

    &[data-sticky='end'] {
      position: sticky;
      inset-inline-end: 0;
      z-index: var(--moduix-table-sticky-column-z-index, 2);
      background-color: var(
        --moduix-table-sticky-column-bg,
        var(--moduix-table-scroll-area-bg, var(--moduix-color-card))
      );
    }
  }

  .root[data-sticky-header] .header .columnHeader[data-sticky] {
    z-index: var(--moduix-table-sticky-intersection-z-index, 4);
  }

  .columnHeader {
    color: var(--moduix-table-column-header-color, var(--moduix-color-muted-foreground));
    font-weight: var(--moduix-table-column-header-font-weight, var(--moduix-weight-medium));
    text-align: inherit;
    white-space: nowrap;
  }

  .cell {
    color: inherit;
  }

  .numeric {
    text-align: end;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
  }

  .empty {
    padding-block: var(--moduix-table-empty-padding-y, var(--_table-empty-padding-y-default));
    color: var(--moduix-table-empty-color, var(--moduix-color-muted-foreground));
    text-align: center;
  }
}
